    { id: 'intro', t: 'Tanışma', d: 'Kendini tanıt, sorular sor.', role: 'Mia, a friendly person meeting the learner for the first time at a party in Berlin (they say du)', open: 'Hallo! Ich bin Mia. Wie heißt du, und woher kommst du?', open_tr: 'Merhaba! Ben Mia. Adın ne, nerelisin?' },
    { id: 'day', t: 'Günün nasıl geçti?', d: 'Bugün ya da dün yaptıkların.', role: 'Mia, a friend asking about the learner\'s day (they say du)', open: 'Hey! Wie war dein Tag? Hast du etwas Interessantes gemacht?', open_tr: 'Selam! Günün nasıl geçti? İlginç bir şey yaptın mı?' },
    { id: 'food', t: 'Kafede', d: 'Sipariş ver, soru sor, hesabı iste.', role: 'Mia, a waiter at a small café in Munich called Café Linde (formal Sie)', open: 'Guten Tag und willkommen im Café Linde! Was darf ich Ihnen bringen?', open_tr: 'İyi günler, Café Linde\'ye hoş geldiniz! Size ne getirebilirim?' },
    { id: 'hotel', t: 'Otelde', d: 'Giriş yap, oda ve kahvaltı hakkında sor.', role: 'Mia, a receptionist at a hotel in Vienna (formal Sie)', open: 'Guten Tag und herzlich willkommen! Haben Sie eine Reservierung?', open_tr: 'İyi günler, hoş geldiniz! Rezervasyonunuz var mı?' },
    { id: 'shop', t: 'Alışveriş', d: 'Beden, renk, fiyat sor.', role: 'Mia, a shop assistant in a clothes shop in Zurich (formal Sie)', open: 'Guten Tag! Kann ich Ihnen helfen? Suchen Sie etwas Bestimmtes?', open_tr: 'İyi günler! Yardımcı olabilir miyim? Belirli bir şey mi arıyorsunuz?' },
    { id: 'hobby', t: 'Hobiler', d: 'Boş zamanında neler yaptığın.', role: 'Mia, a new friend who wants to know about the learner\'s hobbies (they say du)', open: 'Sag mal, was machst du gern in deiner Freizeit?', open_tr: 'Söylesene, boş zamanında ne yapmayı seversin?' },
    { id: 'job', t: 'İş görüşmesi', d: 'Kendini ve deneyimini anlat.', role: 'Mia, an interviewer at a company in Hamburg for a job the learner applied for (formal Sie)', open: 'Guten Morgen, schön, dass Sie da sind! Können Sie sich bitte kurz vorstellen?', open_tr: 'Günaydın, geldiğiniz için memnunuz! Kendinizi kısaca tanıtabilir misiniz?' }
